import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2022-02-03","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-02-03","date":"2022-02-03T00:00:00.000Z","updated":"2022-02-04T00:00:00.000Z","tags":["Ceph","性能优化","内存管理","分布式存储","CRUSH算法","Quincy","MClock"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-02-03.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-02-03.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-02-03.md"};function o(n,e,s,c,h,d){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li>本次会议主要讨论了Ceph性能优化和内存管理相关议题。</li><li>PR活动主要集中在Quincy特性开发上，没有新或关闭的PR。</li><li>有一个关于默认编译跟踪的PR被更新，RBD团队正在审查。</li><li>发现一个可能导致性能回归的PR，与跟踪功能相关，需要密切关注。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>性能优化</strong>: 讨论了通过调整配置和优化代码来减少内存使用和提高性能的方法。</li><li><strong>MClock配置文件</strong>: 讨论了不同MClock配置文件（高客户端IO、高恢复操作、平衡）及其对不同操作（如恢复和scrubbing）的影响。</li><li><strong>Ceph性能测试</strong>: 讨论了在大型集群上使用CBT进行性能测试的计划，特别是关于MClock和scrubbing的测试。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>决定在Giba集群上运行CBT以测试MClock配置文件和scrubbing性能。</li><li>决定进一步研究内存使用情况，特别是通过调整tc_malloc线程缓存和优化内存分配策略。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Mark将设置Giba集群以便进行CBT测试。</li><li>Ashwarya和Sridhar将使用此集群进行MClock和scrubbing的性能测试。</li><li>继续研究并优化内存使用，特别是通过改进内存分配和减少碎片化。</li><li>继续监控和分析可能导致性能回归的PR。</li><li>探索在客户端区域进行CRUSH计算的成本和可扩展性。</li><li>与SpeedyB和DigitalOcean合作，测试RocksDB性能改进。</li></ul>',9)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
